let startTime = new Date(event.metadata.MissedPointChanges.LastRunMaxTime);
// add one millisecond and IntervalMilliseconds * loopIndex
startTime = startTime.getTime() + 1 + (event.metadata.IntervalMilliseconds * event.metadata.loopIndex);
stage.setMetadata("StartTime", new Date(startTime).toISOString());
stage.setValue(event.value);

let endTime = new Date(event.metadata.MissedPointChanges.LastRunMaxTime);
endTime = endTime.getTime() + (event.metadata.IntervalMilliseconds * (event.metadata.loopIndex + 1));
if (new Date(endTime) > event.metadata.MissedPointChanges.CurrentSubscriptionTime)
{
    endTime = event.metadata.MissedPointChanges.CurrentSubscriptionTime;
}
stage.setMetadata("EndTime", new Date(endTime).toISOString());
stage.setValue(event.value);

